from pathlib import Path
import json,hashlib
p=Path(__file__).resolve().parent;b=p.parent.parent
rows=json.loads((p/'literal-records.json').read_text());prov={x['id']:x for x in map(json.loads,(p/'source-provenance.jsonl').read_text().splitlines())}
with (p/'literal-records.raw.jsonl').open('wb') as f:
 for r in rows:
  z=prov[r['mathdb_id']];raw=Path(z['path']).read_bytes().splitlines(keepends=True)[z['line']-1];assert hashlib.sha256(raw).hexdigest()==z['line_sha256'];f.write(raw)
